from auth.tokens import DEPRECATED_TOKEN_KEY
from services.user_service import User

def user_to_dict(user):
    return {
        "user_id": user.user_id,
        "email": user.email,
        "password_hash": user.password_hash  # Include password hash in dictionary
    }

def dict_to_user(data):
    return User(
        data["user_id"],
        data["email"],
        password_hash=data.get("password_hash", None)  # Set password hash if available
    )

def check_legacy_header(headers):
    return headers.get("X-Legacy-Token") == DEPRECATED_TOKEN_KEY
